// Krylov least-squares/least-norm battery -- solver x matrix-regime cross-coverage for the
// rectangular Krylov family, driven through the IdoubleLstsqSolverInvoker struct-functor shape
// (see KrylovBattery.Invokers.double.cs). Two distinct correctness oracles selected by matrix
// shape: Overdetermined (lsqr, lsmr) -- min-RESIDUAL, checked via the fresh normal-equations
// optimality residual ‖Aᵀ(Ax-b)‖ plus elementwise agreement with a direct dense QR least-squares
// solve (check #10); Underdetermined (craig, craigmr) -- min-NORM, checked via the fresh ‖Ax-b‖
// plus elementwise agreement with LQ.minNormSolve (check #11). Check #12 (damped path) only
// applies to the Overdetermined family -- craig/craigmr have no Tikhonov-damped production entry
// point (a consistent min-norm system has no residual/norm trade-off to regularize). No BSR
// gallery matrix is Rectangular today, so this battery drives the dense literature gallery only.
public class doubleKrylovLstsqBatteryTests
{
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct TestJob : IJob
    {
        public enum SolverKind { Lsqr, Lsmr, Craig, Craigmr, Cgne }

        public SolverKind Kind;

        // [0] flag (1 = failure recorded) [1] matrix-enum-as-int [2] check-id [3] got [4] expected
        public NativeArray<double> Fail;

        const int DenseCount = (int)GalleryDenseMatrix.RandSPDIllCond20 + 1;

        public void Execute()
        {
            BurstProbe.RequireBursted();
            switch (Kind)
            {
                case SolverKind.Lsqr:    RunStandardChecks(new doubleLsqrInvoker { TolValue = Consts.doubleSqrtEps, MaxIterMul = 20 }); break;
                case SolverKind.Lsmr:    RunStandardChecks(new doubleLsmrInvoker { TolValue = Consts.doubleSqrtEps, MaxIterMul = 20 }); break;
                case SolverKind.Craig:   RunStandardChecks(new doubleCraigInvoker { TolValue = Consts.doubleSqrtEps, MaxIterMul = 20 }); break;
                case SolverKind.Craigmr: RunStandardChecks(new doubleCraigmrInvoker { TolValue = Consts.doubleSqrtEps, MaxIterMul = 20 }); break;
                // CGNE runs CG directly on AAᵀ (κ² sensitivity), so its solution error scales as
                // cond(A)²·(residual tol) vs craig's cond(A)·(residual tol). Drive the residual an
                // order of magnitude tighter than craig so x still lands inside check #11's shared
                // 50·sqrtEps element band on the well-conditioned WideRandom10x30 (the only
                // underdetermined full-rank entry); the #11 residual bound (10·Tol·‖b‖) scales with
                // Tol in lockstep, so it stays satisfied. See doubleCgneInvoker's doc.
                case SolverKind.Cgne:    RunStandardChecks(new doubleCgneInvoker { TolValue = Consts.doubleSqrtEps * (double)0.1, MaxIterMul = 20 }); break;
            }
        }

        void RunStandardChecks<TInvoker>(TInvoker inv) where TInvoker : struct, IdoubleLstsqSolverInvoker
        {
            for (int i = 0; i < DenseCount; i++)
            {
                var gm = (GalleryDenseMatrix)i;
                if (MatrixProfileMatch.Applicable(inv.Requires, inv.Forbids, GalleryProfiles.Of(gm)))
                    CheckDense(inv, gm);
            }
        }

        // Checks #10-12 (SS5.4) on one dense literature-gallery matrix. Branches the oracle by
        // shape: Overdetermined -> min-residual (#10), Underdetermined -> min-norm (#11). #12
        // (damped path) only runs for Overdetermined invokers.
        void CheckDense<TInvoker>(TInvoker inv, GalleryDenseMatrix gm) where TInvoker : struct, IdoubleLstsqSolverInvoker
        {
            var arena = new Arena(Allocator.Persistent);

            var A = doubleKrylovBatteryGallery.Build(ref arena, gm);
            int m = A.M_Rows, n = A.N_Cols;
            var Aop = new doubleDenseOperator(in A);
            MatrixProfile tags = GalleryProfiles.Of(gm);
            double tolBand = TolBand(tags);
            bool overdetermined = (tags & MatrixProfile.Overdetermined) != 0;
            int checkId = overdetermined ? 10 : 11;

            var b = arena.doubleRandomVec(m, (double)(-1), (double)1, 0xD200u + (uint)gm);

            inv.Init(ref arena, m, n);

            var rScratch = arena.doubleVec(m);
            var sScratch = arena.doubleVec(n);

            // Fixed scale references matching each family's own internal stopping test: ||A^T b||
            // for lsqr/lsmr's normal-equations criterion, ||b|| for craig/craigmr's residual one.
            Aop.ApplyT(in b, ref sScratch);
            double atbNorm = math.sqrt(Blas.dot(sScratch, sScratch));
            double bNorm = math.sqrt(Blas.dot(b, b));
            double thresh = overdetermined
                ? (double)10 * inv.Tol * math.max(atbNorm, (double)1e-30)
                : (double)10 * inv.Tol * math.max(bNorm, (double)1e-30);

            var x1 = arena.doubleVec(n);
            LstsqInfo info1 = inv.Solve(in Aop, in b, ref x1, (double)0);
            bool statusOk1 = info1.status == IterativeSolveStatus.Converged || info1.status == IterativeSolveStatus.MaxIterations;
            Record(statusOk1, (int)gm, checkId, (double)(int)info1.status, (double)0);

            var audit1 = Krylov.lstsqResidual(in Aop, in b, in x1, (double)0, ref rScratch, ref sScratch);

            if (overdetermined)
            {
                // 10. Overdetermined -> min-residual: fresh normal-equations optimality residual
                // small relative to the same ||A^T b|| scale lsqr/lsmr's own stopping test uses,
                // plus elementwise agreement with a direct dense QR least-squares solve.
                Record((double)audit1.Arnorm <= thresh, (int)gm, 10, (double)audit1.Arnorm, thresh);

                var xRef = ReferenceSolveLstsq(ref arena, in A, in b);
                for (int i = 0; i < n; i++)
                    Record(math.abs(x1[i] - xRef[i]) <= tolBand * ((double)1 + math.abs(xRef[i])), (int)gm, 10, x1[i], xRef[i]);

                // 12. Damped path: damp=0 bit-identical to a second independent plain solve, then
                // damp>0 drives the damped optimality residual under the same threshold (lsqr/
                // lsmr's internal stopping test compares the damped residual against this same
                // fixed ||A^T b|| scale, undiminished by damp).
                var x12a = arena.doubleVec(n);
                LstsqInfo info12a = inv.Solve(in Aop, in b, ref x12a, (double)0);
                for (int i = 0; i < n; i++)
                    Record(x1[i] == x12a[i], (int)gm, 12, x1[i], x12a[i]);

                double damp = (double)0.1;
                var x12b = arena.doubleVec(n);
                LstsqInfo info12b = inv.Solve(in Aop, in b, ref x12b, damp);
                bool statusOk12 = info12b.status == IterativeSolveStatus.Converged || info12b.status == IterativeSolveStatus.MaxIterations;
                Record(statusOk12, (int)gm, 12, (double)(int)info12b.status, (double)0);

                var audit12b = Krylov.lstsqResidual(in Aop, in b, in x12b, damp, ref rScratch, ref sScratch);
                Record((double)audit12b.Arnorm <= thresh, (int)gm, 12, (double)audit12b.Arnorm, thresh);
            }
            else
            {
                // 11. Underdetermined -> min-norm: fresh ||b-Ax|| small relative to ||b|| (craig/
                // craigmr's own stopping scale), plus elementwise agreement with LQ.minNormSolve
                // (the exact minimum-2-norm solution).
                Record((double)audit1.rnorm <= thresh, (int)gm, 11, (double)audit1.rnorm, thresh);

                var xRef = arena.doubleVec(n);
                LQ.minNormSolve(in A, in b, ref xRef);
                for (int i = 0; i < n; i++)
                    Record(math.abs(x1[i] - xRef[i]) <= tolBand * ((double)1 + math.abs(xRef[i])), (int)gm, 11, x1[i], xRef[i]);
            }

            arena.Dispose();
        }

        // Direct dense least-squares reference via QR (A must have full column rank, M_Rows >=
        // N_Cols) -- the oracle check #10 compares lsqr/lsmr's iterative solution against.
        doubleN ReferenceSolveLstsq(ref Arena arena, in doubleMxN A, in doubleN b)
        {
            var Q = arena.doubleMat(A.M_Rows, A.N_Cols);
            var R = arena.doubleMat(A.N_Cols);
            QR.decomp(in A, ref Q, ref R);
            doubleN bLocal = b;
            var xRef = arena.doubleVec(A.N_Cols);
            QR.decompSolve(ref Q, ref R, ref bLocal, ref xRef);
            return xRef;
        }

        // WellConditioned -> 50*sqrtEps, IllConditioned -> 5E-2 (mirrors KrylovSquareBatteryTests'
        // own bands).
        static double TolBand(MatrixProfile tags)
            => (tags & MatrixProfile.IllConditioned) != 0 ? (double)5E-2 : (double)50 * Consts.doubleSqrtEps;

        void Record(bool ok, int matrixIdx, int checkId, double got, double expected)
        {
            if (!ok && Fail[0] == (double)0)
            {
                Fail[0] = (double)1;
                Fail[1] = (double)matrixIdx;
                Fail[2] = (double)checkId;
                Fail[3] = got;
                Fail[4] = expected;
            }
            Assert.IsTrue(ok);
        }
    }

